mkdir -p /workspace/dev && cat > /workspace/dev/dump.rs <<'RUSTEOF'
use rust_unit_merge::topology::*;
fn main(){
  let mut args=std::env::args().skip(1).map(|s| s.parse::<usize>().unwrap());
  let code=args.next().unwrap();
  let a:Vec<usize>=(0..7).map(|_|args.next().unwrap()).collect();
  let case=match code {
    0=>build_clos(a[0],1,None,None,a[2]!=0,if a[1]==0 {ClosSourceGroupScope::Tor}else{ClosSourceGroupScope::Pod}),
    1=>build_leaf_spine(a[0],a[1],1),
    2=>build_torus2d(a[0],1,if a[1]==0 {Torus2DSourceGroupScope::Host}else{Torus2DSourceGroupScope::Row}),
    3=>build_torus3d(a[0],1,if a[1]==0 {Torus3DSourceGroupScope::Host}else{Torus3DSourceGroupScope::Line}),
    4=>build_dragonfly(a[0],a[1],a[2],Some(1),1.0,1,0,match a[3]{0=>DragonflySourceGroupScope::Router,1=>DragonflySourceGroupScope::Group,_=>DragonflySourceGroupScope::SourceTargetGroup}),
    5=>build_dragonfly_plus(a[0],a[1],a[2],a[3],a[4]!=0,1,0,if a[5]==0{DragonflyPlusSourceGroupScope::Tor}else{DragonflyPlusSourceGroupScope::Group}),
    _=>panic!("code"),
  };
  let p=&case.problem;
  let mut out=String::new();
  out.push_str(&format!("{}\t{}\n",p.num_nodes,p.demands.len()));
  for d in &p.demands { out.push_str(&format!("{}\t{}\t{}\n",d.src,d.dst,d.footprint.iter().cloned().collect::<std::collections::BTreeSet<_>>().into_iter().map(|x|x.to_string()).collect::<Vec<_>>().join(" "))); }
  print!("{}",out);
}
RUSTEOF
cd /workspace/dev && LD_LIBRARY_PATH=/opt/rust/lib /opt/rust/bin/rustc --edition=2021 --target x86_64-unknown-linux-musl -C opt-level=2 -A warnings --crate-name dump dump.rs --extern rust_unit_merge=/workspace/tmp/unit-merge-build/librust_unit_merge.rlib -o /workspace/dev/dump 2>&1 | head -20; echo "rc=$?"; ls -la /workspace/dev
